import type { ImageSource } from 'expo-image';

import type { PupPose } from './PupArt';

// Generated by `npm run pups` from apps/mobile/assets/pups/. Do not edit by hand.
// Missing images fall back to the labeled placeholder card.
const images: Partial<Record<string, ImageSource>> = {
  'beagle-thriving': require('../../assets/pups/beagle-thriving.png'),
  'beagle-content': require('../../assets/pups/beagle-content.png'),
  'beagle-mopey': require('../../assets/pups/beagle-mopey.png'),
  'beagle-sleeping': require('../../assets/pups/beagle-sleeping.png'),
  'beagle-eating': require('../../assets/pups/beagle-eating.png'),
  'golden-thriving': require('../../assets/pups/golden-thriving.png'),
  'golden-content': require('../../assets/pups/golden-content.png'),
  'golden-mopey': require('../../assets/pups/golden-mopey.png'),
  'golden-sleeping': require('../../assets/pups/golden-sleeping.png'),
  'golden-eating': require('../../assets/pups/golden-eating.png'),
  'corgi-thriving': require('../../assets/pups/corgi-thriving.png'),
  'corgi-content': require('../../assets/pups/corgi-content.png'),
  'corgi-mopey': require('../../assets/pups/corgi-mopey.png'),
  'corgi-sleeping': require('../../assets/pups/corgi-sleeping.png'),
  'corgi-eating': require('../../assets/pups/corgi-eating.png'),
};

export function pupImage(breed: string, pose: PupPose): ImageSource | undefined {
  return images[`${breed}-${pose}`];
}
